// Parity test: extract the <script id="core"> block from app.html, run it in node:vm,
// and compare every field against tests/vectors.json generated by the Python library.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import vm from "node:vm";

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, "app.html"), "utf8");
const m = html.match(/<script id="core">([\s\S]*?)<\/script>/);
if (!m) { console.error("core script block not found"); process.exit(1); }
const ctx = vm.createContext({});
vm.runInContext(m[1] + "\nthis.CementCore = CementCore;", ctx);
const C = ctx.CementCore;
const V = JSON.parse(readFileSync(join(here, "..", "tests", "vectors.json"), "utf8"));
const REL = V.tolerance_rel, ABS = V.tolerance_abs;

let checks = 0, fails = 0;
function fail(msg) { fails++; console.error("FAIL " + msg); }
function close(a, b, where) {
  if (b === null) { checks++; if (a !== null) fail(`${where}: js=${a} py=null`); return; }
  if (Array.isArray(b)) {
    if (!Array.isArray(a) || a.length !== b.length) { checks++; fail(`${where}: array length`); return; }
    b.forEach((x, i) => close(a[i], x, `${where}[${i}]`));
    return;
  }
  if (typeof b === "object") {
    if (a === null || typeof a !== "object") { checks++; fail(`${where}: not an object`); return; }
    const ka = Object.keys(a).sort().join(","), kb = Object.keys(b).sort().join(",");
    checks++;
    if (ka !== kb) fail(`${where}: keys differ js=[${ka}] py=[${kb}]`);
    for (const k of Object.keys(b)) close(a[k], b[k], `${where}.${k}`);
    return;
  }
  checks++;
  if (typeof b === "string" || typeof b === "boolean") { if (a !== b) fail(`${where}: ${a} !== ${b}`); return; }
  const d = Math.abs(a - b);
  if (!(d <= ABS || d <= REL * Math.max(Math.abs(a), Math.abs(b)))) fail(`${where}: js=${a} py=${b} diff=${d}`);
}

let nres = 0, nerr = 0;
for (const c of V.cases) {
  let r = null, err = null;
  try { r = C.evaluate(JSON.parse(JSON.stringify(c.input))); } catch (e) { err = e; }
  if ("error" in c) {
    nerr++; checks++;
    if (!err) fail(`${c.name}: expected error ${c.error}, got a result`);
    else if (err.code !== c.error) fail(`${c.name}: error code ${err.code} !== ${c.error}`);
  } else {
    nres++;
    if (err) { checks++; fail(`${c.name}: unexpected error ${err.message}`); continue; }
    close(JSON.parse(JSON.stringify(r)), c.result, c.name);
  }
}

// Primitive spot checks against hand values.
close(C.capacityBblFt(8.75), 76.5625 / 1029.4, "capacity");
close(C.sacksFor(1.18 * 100, 1.18), 100, "sacks_float_edge");
close(C.sacksFor(100.01, 1), 101, "sacks_round_up");

// Parser checks (same rules as cement_calc.parse).
const p1 = C.parseText('key,value\n\n# comment\nmode,plug\nhole_id_in,8.75,extra\nplug_bottom_md_ft,"9,000"\ntvd_equals_md,yes\n');
close(p1, { mode: "plug", hole_id_in: 8.75, plug_bottom_md_ft: 9000, tvd_equals_md: true }, "parse.csv");
close(C.parseText("hole_id_in\t8.5\npipe_od_in\t3.5\n"), { hole_id_in: 8.5, pipe_od_in: 3.5 }, "parse.tsv");
for (const bad of ["", "   \n", "{bad json", "[1,2]", "hole_id_in,abc", "hole_id_in", "x,nan",
  "lead_density_ppg,11,5", 'lead_density_ppg,"11,5"', 'shoe_md_ft,"15,00"', "shoe_md_ft,1,5000"]) {
  checks++;
  try { C.parseText(bad); fail(`parse accepted ${JSON.stringify(bad)}`); }
  catch (e) { if (e.code !== "file") fail(`parse error code ${e.code} for ${JSON.stringify(bad)}`); }
}

// CSV export cell guard (formula injection).
const cells = [["=CMD|' /c calc'!A1", "'=CMD|' /c calc'!A1"], ["+1+1", "'+1+1"], ["@SUM(A1)", "'@SUM(A1)"], ["-2+3", "'-2+3"],
  ["-12.5", "-12.5"], ["1e-7", "1e-7"], ["lead cased 4500-5000 ft", "lead cased 4500-5000 ft"], ["a,b", '"a,b"'], ['say "hi"', '"say ""hi"""'], [null, ""]];
for (const [inp, want] of cells) { checks++; const got = C.csvCell(inp); if (got !== want) fail(`csvCell(${JSON.stringify(inp)}) = ${JSON.stringify(got)}, want ${JSON.stringify(want)}`); }
// Non-ASCII digits are refused (same as Python).
checks++; try { C.parseText("hole_id_in,\u0668.\u0667\u0665"); fail("parse accepted non-ASCII digits"); } catch (e) { if (e.code !== "file") fail("non-ASCII digits code " + e.code); }

if (fails) { console.error(`${fails} of ${checks} checks failed`); process.exit(1); }
console.log(`parity ok: ${checks} checks across ${nres} result cases and ${nerr} error cases`);
